package events

import (
	"database/sql"
	"encoding/json"
	"errors"
)

// PutSnapshotVersion binds an existing snapshot of documentID to the stable
// version name, all inside one serialized transaction.
//
// The gate (registration then permission) is taken first in the transaction:
// an unregistered device yields store.ErrDeviceNotFound and a revoked device
// store.ErrPermissionDenied, before any snapshot or version is observed. Then
// the target snapshot must exist (a miss, an unknown document included, is
// ErrSnapshotNotFound), and finally the name is resolved:
//
//   - an unbound name is inserted and reports the binding;
//   - a name already bound to the same cursor is idempotent and reports the
//     very same name/cursor pair (the HTTP body is byte-identical to the first
//     registration);
//   - a name already bound to another cursor is *ErrVersionConflict with zero
//     writes.
//
// A version marker never copies or moves snapshot bytes and creates no
// change.
func (s *Service) PutSnapshotVersion(documentID, deviceID, name string, cursor int64) (VersionResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return VersionResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return VersionResult{}, err
	}
	if err := snapshotExistsTx(tx, documentID, cursor); err != nil {
		return VersionResult{}, err
	}

	var existing sql.NullInt64
	err = tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		// An unbound name: insert below.
	case err != nil:
		return VersionResult{}, err
	case existing.Int64 != cursor:
		return VersionResult{}, &ErrVersionConflict{Name: name}
	default:
		// Already bound to the same cursor: idempotent, zero writes.
		if err := tx.Commit(); err != nil {
			return VersionResult{}, err
		}
		return VersionResult{Name: name, Cursor: cursor}, nil
	}
	if _, err := tx.Exec(
		`INSERT INTO snapshot_versions (document_id, name, cursor) VALUES (?, ?, ?)`,
		documentID, name, cursor,
	); err != nil {
		return VersionResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return VersionResult{}, err
	}
	return VersionResult{Name: name, Cursor: cursor}, nil
}

// ListSnapshotVersions returns every version marker of documentID in
// ascending name order, together with the snapshot cursor each points at. The
// gate runs first in the transaction (404 for an unregistered device, 403 for
// a revoked one); an unknown document or a document without markers then
// reads as an empty list rather than an error. It writes nothing.
func (s *Service) ListSnapshotVersions(documentID, deviceID string) ([]SnapshotVersion, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return nil, err
	}

	rows, err := tx.Query(
		`SELECT name, cursor FROM snapshot_versions
		 WHERE document_id = ? ORDER BY name ASC`,
		documentID,
	)
	if err != nil {
		return nil, err
	}
	defer func() { _ = rows.Close() }()

	out := make([]SnapshotVersion, 0)
	for rows.Next() {
		var v SnapshotVersion
		if err := rows.Scan(&v.Name, &v.Cursor); err != nil {
			return nil, err
		}
		out = append(out, v)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return out, tx.Commit()
}

// GetSnapshotVersionState resolves a version name to its snapshot and returns
// that snapshot's cursor and stored state, exactly as GetSnapshot would for
// the cursor. The gate runs first; a name without a marker is
// ErrVersionNotFound and a marker whose snapshot is gone is
// ErrSnapshotNotFound — the caller maps both to 404 and exposes no content.
func (s *Service) GetSnapshotVersionState(documentID, deviceID, name string) (int64, json.RawMessage, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return 0, nil, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return 0, nil, err
	}

	var cursor int64
	err = tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&cursor)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return 0, nil, ErrVersionNotFound
	case err != nil:
		return 0, nil, err
	}

	var state []byte
	if err := tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&state); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return 0, nil, ErrSnapshotNotFound
		}
		return 0, nil, err
	}
	return cursor, json.RawMessage(state), tx.Commit()
}

// RebindSnapshotVersion moves an existing version name of documentID to
// another existing snapshot cursor in one serialized transaction. The gate
// (404/403) is taken first; the named marker must exist (ErrVersionNotFound)
// and the target snapshot must exist (ErrSnapshotNotFound, an unknown
// document included). Rebinding to the cursor already bound is an idempotent
// no-op reporting the same pair; otherwise the marker is updated. The
// snapshot itself is never modified or copied.
func (s *Service) RebindSnapshotVersion(documentID, deviceID, name string, cursor int64) (VersionResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return VersionResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return VersionResult{}, err
	}

	var existing int64
	err = tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&existing)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return VersionResult{}, ErrVersionNotFound
	case err != nil:
		return VersionResult{}, err
	}
	if err := snapshotExistsTx(tx, documentID, cursor); err != nil {
		return VersionResult{}, err
	}
	if existing != cursor {
		if _, err := tx.Exec(
			`UPDATE snapshot_versions SET cursor = ? WHERE document_id = ? AND name = ?`,
			cursor, documentID, name,
		); err != nil {
			return VersionResult{}, err
		}
	}
	if err := tx.Commit(); err != nil {
		return VersionResult{}, err
	}
	return VersionResult{Name: name, Cursor: cursor}, nil
}

// DeleteSnapshotVersion hard-deletes one version marker of documentID. The
// gate (404/403) is taken first; a name without a marker is
// ErrVersionNotFound. The snapshot is left untouched; once the marker commits
// the name is free to bind again.
func (s *Service) DeleteSnapshotVersion(documentID, deviceID, name string) error {
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return err
	}

	var bound int64
	if err := tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&bound); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrVersionNotFound
		}
		return err
	}
	if _, err := tx.Exec(
		`DELETE FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	); err != nil {
		return err
	}
	return tx.Commit()
}

// RestoreSnapshotVersion resolves a version name of documentID to its
// snapshot and appends that snapshot's state as one ordinary change, with
// exactly the semantics of RestoreSnapshot: the gate is taken first in the
// transaction, a missing marker yields ErrVersionNotFound and a missing
// snapshot ErrSnapshotNotFound, after which the shared restore path decides
// idempotency and conflict (an id occupied by an ordinary change is 409). The
// document cursor advances by one on a genuinely new restore and the long
// polls and subscribers are woken.
func (s *Service) RestoreSnapshotVersion(documentID, deviceID, changeID, name string) (RestoreResult, error) {
	tx, err := s.db.Begin()
	if err != nil {
		return RestoreResult{}, err
	}
	defer func() { _ = tx.Rollback() }()

	if err := gateTx(s, tx, documentID, deviceID); err != nil {
		return RestoreResult{}, err
	}

	var snapshotCursor int64
	err = tx.QueryRow(
		`SELECT cursor FROM snapshot_versions WHERE document_id = ? AND name = ?`,
		documentID, name,
	).Scan(&snapshotCursor)
	switch {
	case errors.Is(err, sql.ErrNoRows):
		return RestoreResult{}, ErrVersionNotFound
	case err != nil:
		return RestoreResult{}, err
	}

	result, err := restoreSnapshotTx(tx, documentID, deviceID, changeID, snapshotCursor)
	if err != nil {
		return RestoreResult{}, err
	}
	if err := tx.Commit(); err != nil {
		return RestoreResult{}, err
	}
	if result.Created {
		s.notifyWaiters(documentID)
	}
	return result, nil
}

// gateTx runs the service's registration/permission gate inside tx. A service
// built without a gate (some service-level tests) skips the verdict.
func gateTx(s *Service, tx *sql.Tx, documentID, deviceID string) error {
	if s.gate == nil {
		return nil
	}
	return s.gate.DeviceAuthorizedTx(tx, documentID, deviceID)
}

// snapshotExistsTx reports whether documentID has a snapshot at cursor,
// returning ErrSnapshotNotFound on a miss. It runs inside the caller's
// serialized transaction so the existence verdict and the following write are
// one judgment.
func snapshotExistsTx(tx *sql.Tx, documentID string, cursor int64) error {
	var state []byte
	if err := tx.QueryRow(
		`SELECT state FROM snapshots WHERE document_id = ? AND cursor = ?`,
		documentID, cursor,
	).Scan(&state); err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return ErrSnapshotNotFound
		}
		return err
	}
	return nil
}

// Package events is the change event service: the durable per-document change
// log together with everything written on top of it.
//
// Within a document every change has a client-supplied id. New ids receive a
// monotonically increasing cursor; re-posting an existing id is idempotent
// only when the deviceId and decoded JSON payload match, otherwise it is a
// conflict. Valid batches commit atomically in one serialized transaction, so
// cursors never repeat and no record is partially written, even under
// concurrent writers. Ordinary posts, offline replays, merges and snapshot
// restores all allocate from the same per-document contiguous cursor space.
//
// A document may also carry snapshots: caller-supplied JSON states pinned to
// existing change cursors. Snapshots are write-once per cursor — a matching
// re-post is idempotent, a differing one a conflict — and live apart from the
// change log. A restore appends an ordinary change whose payload is a
// snapshot's state, recording its provenance so a repeated restore after a
// restart keeps the same idempotency/conflict decisions.
//
// Reads page by cursor in ascending order. The session view and the document
// view are the same read; the HTTP layer adds the session/permission checks.
// Long polling and push subscriptions are in-memory observers of commits:
// they register before the confirming read, hold no durable state, and are
// woken only after a change-bearing transaction has committed.
//
// The service owns only its own tables. The registration and permission
// layers are reached through its Gate interface, so a replay or merge never
// reaches into another service's storage.
package events

import (
	"encoding/json"
	"errors"
	"fmt"
)

// ErrStoreClosing reports that the service is shutting down and parked long
// polls have been woken so they can return without writing anything. The
// caller maps it to 503.
var ErrStoreClosing = errors.New("store is closing")

// Change is one element of an inbound batch or one row of a listing.
type Change struct {
	ID       string          // client-supplied change id, unique per document
	DeviceID string          // originating device
	Payload  json.RawMessage // decoded JSON value, stored verbatim
}

// Result reports the outcome for one element of an accepted batch.
type Result struct {
	ID      string `json:"id"`
	Created bool   `json:"created"`
	Cursor  int64  `json:"cursor"`
}

// ListedChange is one row in a ListChanges response.
type ListedChange struct {
	ID       string          `json:"id"`
	DeviceID string          `json:"deviceId"`
	Payload  json.RawMessage `json:"payload"`
	Cursor   int64           `json:"cursor"`
}

// MergeResult reports the outcome of an accepted MergeChange. Outcome is one
// of "idempotent", "applied" or "merged".
type MergeResult struct {
	ID      string  `json:"id"`
	Outcome string  `json:"outcome"`
	Cursor  int64   `json:"cursor"`
	Result  *Result `json:"result,omitempty"`
}

// ErrConflict reports that a batch references an existing change id with a
// different deviceId or payload. The whole batch is rejected.
type ErrConflict struct {
	ID string
}

func (e *ErrConflict) Error() string {
	return fmt.Sprintf("conflicting change %q for document", e.ID)
}

// ErrStaleCursor reports that a merge targets a base cursor for an unknown
// document, or a base cursor greater than the document's current cursor. The
// caller maps it to 400; nothing is written.
var ErrStaleCursor = errors.New("baseCursor is unknown or ahead of the current cursor")

// ErrSnapshotBase reports that a snapshot targets an unknown document or a
// cursor that is not an existing change cursor of the document. The caller
// maps it to 400; nothing is written.
var ErrSnapshotBase = errors.New("snapshot cursor is not an existing cursor of the document")

// ErrCompactedBase reports that a merge targets a base cursor below the
// document's compaction boundary: the changes it would be checked against
// have left the online log, so the conflict check cannot be completed. The
// caller maps it to 400; nothing is written.
var ErrCompactedBase = errors.New("baseCursor is below the compaction boundary")

// ErrSnapshotNotFound reports that no snapshot exists for the document and
// cursor. The caller maps it to 404.
var ErrSnapshotNotFound = errors.New("snapshot not found")

// ErrSnapshotConflict reports that a snapshot already exists for the document
// and cursor with a different state. The stored snapshot is left unchanged.
type ErrSnapshotConflict struct {
	Cursor int64
}

func (e *ErrSnapshotConflict) Error() string {
	return fmt.Sprintf("conflicting snapshot for cursor %d", e.Cursor)
}

// ErrRestoreConflict reports that a restore references a change id that is
// already taken by an ordinary change, or by a prior restore whose deviceId,
// snapshot cursor or source state differs. Nothing is written; the caller maps
// it to 409.
type ErrRestoreConflict struct {
	ID string
}

func (e *ErrRestoreConflict) Error() string {
	return fmt.Sprintf("change id %q conflicts with the change log", e.ID)
}

// ExportedSnapshot is one row of an ExportSnapshots result.
type ExportedSnapshot struct {
	Cursor int64           `json:"cursor"`
	State  json.RawMessage `json:"state"`
}

// ErrVersionConflict reports that a version registration or rename cannot be
// applied: the version name is already bound to a different snapshot cursor,
// or the requested bind would move an existing name (and zero writes is the
// required outcome). The caller maps it to 409.
type ErrVersionConflict struct {
	Name string
}

func (e *ErrVersionConflict) Error() string {
	return fmt.Sprintf("snapshot version %q is bound to another cursor", e.Name)
}

// ErrVersionNotFound reports that no snapshot version of the document carries
// the requested name. The caller maps it to 404.
var ErrVersionNotFound = errors.New("snapshot version not found")

// SnapshotVersion is one row of a ListSnapshotVersions result: the version
// name together with the snapshot cursor it points at.
type SnapshotVersion struct {
	Name   string `json:"name"`
	Cursor int64  `json:"snapshotCursor"`
}

// VersionResult reports the outcome of registering or renaming a snapshot
// version: the version name and the snapshot cursor it is bound to. An
// idempotent registration returns the same body as the first registration.
type VersionResult struct {
	Name   string `json:"name"`
	Cursor int64  `json:"snapshotCursor"`
}

// RestoreResult reports the outcome of an accepted RestoreSnapshot.
type RestoreResult struct {
	ID           string `json:"id"`
	Created      bool   `json:"created"`
	Cursor       int64  `json:"cursor"`
	RestoredFrom int64  `json:"restoredFrom"`
}

// schema is created when the service is constructed. Table and index shapes
// are unchanged from the pre-refactor layout, so data already on disk stays
// readable.
const schema = `
CREATE TABLE IF NOT EXISTS changes (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	id          TEXT NOT NULL,
	device_id   TEXT NOT NULL,
	payload     BLOB NOT NULL,
	PRIMARY KEY (document_id, id)
);
CREATE UNIQUE INDEX IF NOT EXISTS changes_doc_cursor_idx
	ON changes(document_id, cursor);
CREATE TABLE IF NOT EXISTS snapshots (
	document_id TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	state       BLOB NOT NULL,
	PRIMARY KEY (document_id, cursor)
);
CREATE TABLE IF NOT EXISTS restores (
	document_id     TEXT NOT NULL,
	change_id       TEXT NOT NULL,
	device_id       TEXT NOT NULL,
	snapshot_cursor INTEGER NOT NULL,
	change_cursor   INTEGER NOT NULL,
	state           BLOB NOT NULL,
	PRIMARY KEY (document_id, change_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS restores_doc_cursor_idx
	ON restores(document_id, change_cursor);
CREATE TABLE IF NOT EXISTS change_boundaries (
	document_id TEXT NOT NULL PRIMARY KEY,
	boundary    INTEGER NOT NULL
);
CREATE TABLE IF NOT EXISTS change_identities (
	document_id   TEXT NOT NULL,
	id            TEXT NOT NULL,
	device_id     TEXT NOT NULL,
	digest        BLOB NOT NULL,
	cursor        INTEGER NOT NULL,
	restored_from INTEGER,
	PRIMARY KEY (document_id, id)
);
CREATE TABLE IF NOT EXISTS snapshot_versions (
	document_id TEXT NOT NULL,
	name        TEXT NOT NULL,
	cursor      INTEGER NOT NULL,
	PRIMARY KEY (document_id, name)
);
`

// Document-level deletion removes every durable row a document owns in the
// change event service: the online change log, the compaction boundary, the
// retained idempotency summaries of trimmed changes, snapshots and restore
// provenance. After the deletion the same document id is a brand-new document:
// an unknown document reads as an empty list at cursor 0, and the next commit
// allocates cursor 1 again, because every row — the boundary included — that
// remembered the old cursor space is gone.
//
// The work runs inside the caller's serialized transaction, sharing it with the
// CRDT state and permission-ledger deletions of the same operation, so a
// document deletion either removes every row or none; a document with no row
// in any of the services misses (ErrDocumentNotFound) and writes nothing.

package events

import (
	"errors"

	"github.com/alicegogogogogo/local-first-sync-service/internal/store"
)

// ErrDocumentNotFound reports that a delete targets a document id that has no
// durable data anywhere — it was never created or was already deleted. The
// caller maps it to 404; nothing is written.
var ErrDocumentNotFound = errors.New("document not found")

// DocumentDataExistsTx reports whether the change event service holds any row
// for documentID: an online change, a compaction boundary, a retained
// trimmed-id summary, a snapshot, a snapshot version marker or a restore
// record. It runs inside the caller's transaction so the existence verdict is
// one judgment with the deletion that follows it.
func (s *Service) DocumentDataExistsTx(q store.DBTX, documentID string) (bool, error) {
	var exists bool
	if err := q.QueryRow(
		`SELECT EXISTS(SELECT 1 FROM changes WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_boundaries WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM change_identities WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM snapshots WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM snapshot_versions WHERE document_id = ?)
		 OR EXISTS(SELECT 1 FROM restores WHERE document_id = ?)`,
		documentID, documentID, documentID, documentID, documentID, documentID,
	).Scan(&exists); err != nil {
		return false, err
	}
	return exists, nil
}

// DeleteDocumentDataTx removes every change-event row of documentID inside the
// caller's serialized transaction: the online log and restore records first
// (the rows that reference cursors), then snapshots and their named version
// markers, the retained idempotency summaries and finally the compaction
// boundary. With the boundary gone the cursor space restarts from 1 when the
// id is created again, and with the markers gone a re-created document of the
// same name inherits no version. It does not judge existence — the caller
// checks DocumentDataExistsTx (and the CRDT service's equivalent) once before
// deleting — so it never returns ErrDocumentNotFound on its own.
func (s *Service) DeleteDocumentDataTx(q store.DBTX, documentID string) error {
	stmts := []string{
		`DELETE FROM restores WHERE document_id = ?`,
		`DELETE FROM changes WHERE document_id = ?`,
		`DELETE FROM snapshot_versions WHERE document_id = ?`,
		`DELETE FROM snapshots WHERE document_id = ?`,
		`DELETE FROM change_identities WHERE document_id = ?`,
		`DELETE FROM change_boundaries WHERE document_id = ?`,
	}
	for _, stmt := range stmts {
		if _, err := q.Exec(stmt, documentID); err != nil {
			return err
		}
	}
	return nil
}

