			// snapshot at restoredFrom, so matching device and snapshot cursor
			// means the same source state even once that snapshot is pruned.
			// When the snapshot still exists, compare its state exactly as a
			// fresh restore would.
			if ifm, ok, err := snapshotStateIfExistsTx(tx, documentID, snapshotCursor); err != nil {
				return RestoreResult{}, err
