		versionsRestore := len(segs) == 5 && segs[0] != "" && segs[2] == "versions" && segs[3] != "" && segs[4] == "restore"
		return !(collection || cursorItem || prune || versionsCollection || versionsItem || versionsRestore)
	}
	return false
}

