// recordedRestoreVerdictTx answers the idempotency/conflict question for an id
// that already names a recorded restore, from its stored provenance:
// originDevice is the recorded source device, firstCursor the cursor the
// change was first assigned and digest the canonical digest of the state the
// snapshot carried when the restore happened (trimmed summarizes the digest;
// an online restores row passes the digest of its stored state).
//
// The same device and snapshot cursor mean the same source state, so the
// verdict survives the pruning of that snapshot (and the caller repeats as
// idempotent with the first cursor); a different device or snapshot cursor is
// a conflict. When the snapshot still exists, its live state is compared to
// the recorded digest as well, exactly as a fresh restore would. trimmed
// distinguishes the retained-summary and online paths only for the digest
// comparison shape.
func recordedRestoreVerdictTx(tx *sql.Tx, changeID, deviceID string, snapshotCursor, originDevice, firstCursor int64, digest []byte, trimmed bool) (RestoreResult, error) {
	if originDevice != deviceID {
		return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
	}
	_ = trimmed
	// The recorded snapshot cursor is implicit in the stored provenance; the
	// caller already matched it before reaching here, but compare again to
	// keep the verdict self-contained.
	var recordedCursor int64
	switch err := tx.QueryRow(
		`SELECT COALESCE((SELECT snapshot_cursor FROM restores WHERE document_id = ? AND change_id = ?),
		                (SELECT restored_from FROM change_identities WHERE document_id = ? AND id = ?))`,
		documentIDForRestore, changeID, documentIDForRestore, changeID,
	).Scan(&recordedCursor); {
	case err != nil:
		return RestoreResult{}, err
	}
	if recordedCursor != snapshotCursor {
		return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
	}
	if state, ok, err := snapshotStateIfExistsTx(tx, documentIDForRestore, snapshotCursor); err != nil {
		return RestoreResult{}, err
	} else if ok {
		liveDigest, err := payloadDigest(state)
		if err != nil {
			return RestoreResult{}, err
		}
		if !bytes.Equal(digest, liveDigest) {
			return RestoreResult{}, &ErrRestoreConflict{ID: changeID}
		}
	}
	return RestoreResult{
		ID:           changeID,
		Created:      false,
		Cursor:       firstCursor,
		RestoredFrom: snapshotCursor,
	}, nil
}

